using LPARAM = std::int64_t;
using UINT = std::uint32_t;

LPARAM makeLParam(int lo, int hi) { return 0; }
int loWord(LPARAM v) { return 0; }
int hiWord(LPARAM v) { return 0; }
int getX(LPARAM v) { return 0; }
int getY(LPARAM v) { return 0; }
std::string messageRange(UINT msg) { return ""; }

solution.solution.cpp:
#include <cstdint>
#include <string>

using WPARAM = std::uint64_t;
using LPARAM = std::int64_t;
using UINT = std::uint32_t;

LPARAM makeLParam(int lo, int hi)
{
    const std::uint32_t packed{ (static_cast<std::uint32_t>(lo) & 0xFFFFu) | ((static_cast<std::uint32_t>(hi) & 0xFFFFu) << 16) };
    return static_cast<LPARAM>(packed);
}

int loWord(LPARAM v) { return static_cast<int>(static_cast<std::uint64_t>(v) & 0xFFFFu); }
int hiWord(LPARAM v) { return static_cast<int>((static_cast<std::uint64_t>(v) >> 16) & 0xFFFFu); }
int getX(LPARAM v) { return static_cast<std::int16_t>(loWord(v)); }
int getY(LPARAM v) { return static_cast<std::int16_t>(hiWord(v)); }

std::string messageRange(UINT msg)
{
    if (msg < 0x0400) return "system";
    if (msg < 0x8000) return "class";
    if (msg < 0xC000) return "app";
    if (msg <= 0xFFFF) return "registered";
    return "reserved";
}

unitTests:
TEST("packing") { CHECK_EQ(makeLParam(800, 500), LPARAM{ 0x01F40320 }); CHECK_EQ(loWord(makeLParam(800, 500)), 800); CHECK_EQ(hiWord(makeLParam(800, 500)), 500); }
TEST("negative positions") {
    const LPARAM p = makeLParam(-1, -200);
    CHECK_EQ(loWord(p), 65535); CHECK_EQ(getX(p), -1); CHECK_EQ(getY(p), -200); CHECK_EQ(p, LPARAM{ 0xFF38FFFF });
}
TEST("only the low 32 bits") { const LPARAM v = static_cast<LPARAM>(0x12345678ABCDEF01LL); CHECK_EQ(loWord(v), 0xEF01); CHECK_EQ(hiWord(v), 0xABCD); CHECK_EQ(getX(v), -4351); }
TEST("ranges") {
    CHECK_EQ(messageRange(0x000F), std::string("system")); CHECK_EQ(messageRange(0x0400), std::string("class")); CHECK_EQ(messageRange(0x8001), std::string("app"));
    CHECK_EQ(messageRange(0xC123), std::string("registered")); CHECK_EQ(messageRange(0x10000), std::string("reserved")); CHECK_EQ(messageRange(0x7FFF), std::string("class"));
}

